-- Rollback (manual, not executed by migrate deploy):
-- ## Rollback: z20261015000000_card_price_book
-- Down migration: none is auto-generated by Prisma. Manual SQL, safe because nothing outside the price book references
-- these tables and the flag is off until Patrick turns it on (children first, the FKs point at "PriceBook"):
--   DROP TABLE IF EXISTS "PriceBookRunItem";
--   DROP TABLE IF EXISTS "PriceBookRun";
--   DROP TABLE IF EXISTS "PriceBookLock";
--   DROP TABLE IF EXISTS "PriceBookBulkRate";
--   DROP TABLE IF EXISTS "PriceBookBenchmark";
--   DROP TABLE IF EXISTS "PriceBookReference";
--   DROP TABLE IF EXISTS "PriceBookRule";
--   DROP TABLE IF EXISTS "PriceBook";
--   then delete this migration's _prisma_migrations row.
-- Playbook: If deploy fails at migrate deploy, nothing else changed: the backend build with the flag off never touches
-- these tables, so redeploy the previous build and leave the tables. If the price book was used and must be backed out,
-- first set CARD_PRICE_BOOK_ENABLED to false (routes answer 404, suggestions fall back to the legacy computation), then
-- run the DROP block through prisma db execute --stdin against Railway following the dev-environment checklist, then
-- remove the models from schema.prisma and run prisma generate. Prices already applied to items stay (they are ordinary
-- item prices); only the run ledger and undo are lost.

-- Price book (2026-10-15, ADR-140, batch B1). Additive only: eight new tables, their indexes, foreign keys and CHECK
-- constraints. No existing table or column is changed (Organizer gets only a Prisma relation field, no column).
-- Creates EMPTY tables. No backfill, no seed row. Re-runnable: every statement is IF NOT EXISTS or guarded by pg_constraint.

-- CreateTable
CREATE TABLE IF NOT EXISTS "PriceBook" (
    "id" TEXT NOT NULL,
    "organizerId" TEXT NOT NULL,
    "enabled" BOOLEAN NOT NULL DEFAULT false,
    "version" INTEGER NOT NULL DEFAULT 1,
    "allowCatalogReference" BOOLEAN NOT NULL DEFAULT false,
    "referenceOrder" TEXT[] DEFAULT ARRAY['MANUAL', 'SHOP_SOLD_HISTORY', 'SHOP_BENCHMARK', 'CATALOG_REFERENCE', 'LICENSED_FEED']::TEXT[],
    "retailPercentBps" INTEGER NOT NULL DEFAULT 10000,
    "defaultFloorCents" INTEGER NOT NULL DEFAULT 0,
    "defaultCeilingCents" INTEGER,
    "defaultRoundingMode" TEXT NOT NULL DEFAULT 'TIERED',
    "defaultRoundingDirection" TEXT NOT NULL DEFAULT 'NEAREST',
    "condNmBps" INTEGER NOT NULL DEFAULT 10000,
    "condLpBps" INTEGER NOT NULL DEFAULT 9000,
    "condMpBps" INTEGER NOT NULL DEFAULT 8000,
    "condHpBps" INTEGER NOT NULL DEFAULT 6500,
    "condDmgBps" INTEGER NOT NULL DEFAULT 5000,
    "nonEnglishBps" INTEGER NOT NULL DEFAULT 10000,
    "movementReviewBps" INTEGER NOT NULL DEFAULT 2500,
    "referenceWarnDays" INTEGER NOT NULL DEFAULT 90,
    "referenceMaxDays" INTEGER NOT NULL DEFAULT 365,
    "soldHistoryMinSales" INTEGER NOT NULL DEFAULT 2,
    "soldHistoryMaxSales" INTEGER NOT NULL DEFAULT 5,
    "soldHistoryWindowDays" INTEGER NOT NULL DEFAULT 180,
    "manualLockDays" INTEGER NOT NULL DEFAULT 14,
    "buyCreditBps" INTEGER NOT NULL DEFAULT 12000,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,
    CONSTRAINT "PriceBook_pkey" PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX IF NOT EXISTS "PriceBook_organizerId_key" ON "PriceBook"("organizerId");

CREATE TABLE IF NOT EXISTS "PriceBookRule" (
    "id" TEXT NOT NULL,
    "bookId" TEXT NOT NULL,
    "family" TEXT NOT NULL,
    "name" VARCHAR(80) NOT NULL,
    "priority" INTEGER NOT NULL,
    "enabled" BOOLEAN NOT NULL DEFAULT true,
    "productType" TEXT NOT NULL DEFAULT 'SINGLE',
    "game" TEXT,
    "setCode" TEXT,
    "rarityClass" TEXT,
    "rarityText" VARCHAR(60),
    "finish" TEXT,
    "language" TEXT,
    "variantToken" TEXT,
    "refMinCents" INTEGER,
    "refMaxCents" INTEGER,
    "sourceKinds" TEXT[] DEFAULT ARRAY[]::TEXT[],
    "basis" TEXT NOT NULL DEFAULT 'REFERENCE',
    "percentBps" INTEGER NOT NULL DEFAULT 10000,
    "addCents" INTEGER NOT NULL DEFAULT 0,
    "fixedCents" INTEGER,
    "floorCents" INTEGER,
    "ceilingCents" INTEGER,
    "minMarginBps" INTEGER,
    "roundingMode" TEXT,
    "roundingDirection" TEXT,
    "creditBps" INTEGER,
    "minOfferCents" INTEGER,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,
    CONSTRAINT "PriceBookRule_pkey" PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "PriceBookRule_bookId_family_priority_idx" ON "PriceBookRule"("bookId", "family", "priority");

CREATE TABLE IF NOT EXISTS "PriceBookReference" (
    "id" TEXT NOT NULL,
