-- AddForeignKey (all ON DELETE CASCADE: deleting an Organizer removes the whole book and its ledger)
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'PriceBook_organizerId_fkey') THEN
    ALTER TABLE "PriceBook" ADD CONSTRAINT "PriceBook_organizerId_fkey"
      FOREIGN KEY ("organizerId") REFERENCES "Organizer"("id") ON DELETE CASCADE ON UPDATE CASCADE;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'PriceBookRule_bookId_fkey') THEN
    ALTER TABLE "PriceBookRule" ADD CONSTRAINT "PriceBookRule_bookId_fkey"
      FOREIGN KEY ("bookId") REFERENCES "PriceBook"("id") ON DELETE CASCADE ON UPDATE CASCADE;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'PriceBookReference_bookId_fkey') THEN
    ALTER TABLE "PriceBookReference" ADD CONSTRAINT "PriceBookReference_bookId_fkey"
      FOREIGN KEY ("bookId") REFERENCES "PriceBook"("id") ON DELETE CASCADE ON UPDATE CASCADE;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'PriceBookBenchmark_bookId_fkey') THEN
    ALTER TABLE "PriceBookBenchmark" ADD CONSTRAINT "PriceBookBenchmark_bookId_fkey"
      FOREIGN KEY ("bookId") REFERENCES "PriceBook"("id") ON DELETE CASCADE ON UPDATE CASCADE;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'PriceBookBulkRate_bookId_fkey') THEN
    ALTER TABLE "PriceBookBulkRate" ADD CONSTRAINT "PriceBookBulkRate_bookId_fkey"
      FOREIGN KEY ("bookId") REFERENCES "PriceBook"("id") ON DELETE CASCADE ON UPDATE CASCADE;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'PriceBookLock_bookId_fkey') THEN
    ALTER TABLE "PriceBookLock" ADD CONSTRAINT "PriceBookLock_bookId_fkey"
      FOREIGN KEY ("bookId") REFERENCES "PriceBook"("id") ON DELETE CASCADE ON UPDATE CASCADE;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'PriceBookRun_bookId_fkey') THEN
    ALTER TABLE "PriceBookRun" ADD CONSTRAINT "PriceBookRun_bookId_fkey"
      FOREIGN KEY ("bookId") REFERENCES "PriceBook"("id") ON DELETE CASCADE ON UPDATE CASCADE;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'PriceBookRunItem_runId_fkey') THEN
    ALTER TABLE "PriceBookRunItem" ADD CONSTRAINT "PriceBookRunItem_runId_fkey"
      FOREIGN KEY ("runId") REFERENCES "PriceBookRun"("id") ON DELETE CASCADE ON UPDATE CASCADE;
  END IF;
END $$;

-- AddCheck (named, each guarded so a second run is a no-op)
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'PriceBook_version_min_check') THEN
    ALTER TABLE "PriceBook" ADD CONSTRAINT "PriceBook_version_min_check" CHECK ("version" >= 1);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'PriceBook_retailPercentBps_range_check') THEN
    ALTER TABLE "PriceBook" ADD CONSTRAINT "PriceBook_retailPercentBps_range_check" CHECK ("retailPercentBps" BETWEEN 1 AND 100000);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'PriceBook_condNmBps_range_check') THEN
    ALTER TABLE "PriceBook" ADD CONSTRAINT "PriceBook_condNmBps_range_check" CHECK ("condNmBps" BETWEEN 1 AND 20000);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'PriceBook_condLpBps_range_check') THEN
    ALTER TABLE "PriceBook" ADD CONSTRAINT "PriceBook_condLpBps_range_check" CHECK ("condLpBps" BETWEEN 1 AND 20000);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'PriceBook_condMpBps_range_check') THEN
    ALTER TABLE "PriceBook" ADD CONSTRAINT "PriceBook_condMpBps_range_check" CHECK ("condMpBps" BETWEEN 1 AND 20000);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'PriceBook_condHpBps_range_check') THEN
    ALTER TABLE "PriceBook" ADD CONSTRAINT "PriceBook_condHpBps_range_check" CHECK ("condHpBps" BETWEEN 1 AND 20000);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'PriceBook_condDmgBps_range_check') THEN
    ALTER TABLE "PriceBook" ADD CONSTRAINT "PriceBook_condDmgBps_range_check" CHECK ("condDmgBps" BETWEEN 1 AND 20000);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'PriceBook_nonEnglishBps_range_check') THEN
    ALTER TABLE "PriceBook" ADD CONSTRAINT "PriceBook_nonEnglishBps_range_check" CHECK ("nonEnglishBps" BETWEEN 1 AND 20000);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'PriceBook_movementReviewBps_range_check') THEN
    ALTER TABLE "PriceBook" ADD CONSTRAINT "PriceBook_movementReviewBps_range_check" CHECK ("movementReviewBps" BETWEEN 100 AND 100000);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'PriceBook_referenceWarnDays_range_check') THEN
    ALTER TABLE "PriceBook" ADD CONSTRAINT "PriceBook_referenceWarnDays_range_check" CHECK ("referenceWarnDays" BETWEEN 1 AND 3650);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'PriceBook_referenceMaxDays_range_check') THEN
    ALTER TABLE "PriceBook" ADD CONSTRAINT "PriceBook_referenceMaxDays_range_check" CHECK ("referenceMaxDays" BETWEEN "referenceWarnDays" AND 3650);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'PriceBook_soldHistoryMinSales_range_check') THEN
    ALTER TABLE "PriceBook" ADD CONSTRAINT "PriceBook_soldHistoryMinSales_range_check" CHECK ("soldHistoryMinSales" BETWEEN 1 AND 20);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'PriceBook_soldHistoryMaxSales_range_check') THEN
    ALTER TABLE "PriceBook" ADD CONSTRAINT "PriceBook_soldHistoryMaxSales_range_check" CHECK ("soldHistoryMaxSales" BETWEEN "soldHistoryMinSales" AND 50);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'PriceBook_soldHistoryWindowDays_range_check') THEN
    ALTER TABLE "PriceBook" ADD CONSTRAINT "PriceBook_soldHistoryWindowDays_range_check" CHECK ("soldHistoryWindowDays" BETWEEN 7 AND 1095);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'PriceBook_manualLockDays_range_check') THEN
    ALTER TABLE "PriceBook" ADD CONSTRAINT "PriceBook_manualLockDays_range_check" CHECK ("manualLockDays" BETWEEN 0 AND 365);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'PriceBook_buyCreditBps_range_check') THEN
    ALTER TABLE "PriceBook" ADD CONSTRAINT "PriceBook_buyCreditBps_range_check" CHECK ("buyCreditBps" BETWEEN 10000 AND 30000);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'PriceBook_defaultFloorCents_min_check') THEN
    ALTER TABLE "PriceBook" ADD CONSTRAINT "PriceBook_defaultFloorCents_min_check" CHECK ("defaultFloorCents" >= 0);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'PriceBook_defaultCeilingCents_min_check') THEN
    ALTER TABLE "PriceBook" ADD CONSTRAINT "PriceBook_defaultCeilingCents_min_check" CHECK ("defaultCeilingCents" IS NULL OR "defaultCeilingCents" >= "defaultFloorCents");
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'PriceBook_defaultRoundingMode_values_check') THEN
    ALTER TABLE "PriceBook" ADD CONSTRAINT "PriceBook_defaultRoundingMode_values_check" CHECK ("defaultRoundingMode" IN ('NONE','TIERED','NEAREST_5C','NEAREST_25C','NEAREST_DOLLAR','ENDING_99','KEYSTONE_49_99'));
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'PriceBook_defaultRoundingDirection_values_check') THEN
    ALTER TABLE "PriceBook" ADD CONSTRAINT "PriceBook_defaultRoundingDirection_values_check" CHECK ("defaultRoundingDirection" IN ('NEAREST','UP','DOWN'));
  END IF;
END $$;

DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'PriceBookRule_family_values_check') THEN
    ALTER TABLE "PriceBookRule" ADD CONSTRAINT "PriceBookRule_family_values_check" CHECK ("family" IN ('RETAIL','BUYLIST'));
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'PriceBookRule_productType_single_check') THEN
    ALTER TABLE "PriceBookRule" ADD CONSTRAINT "PriceBookRule_productType_single_check" CHECK ("productType" = 'SINGLE');
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'PriceBookRule_basis_values_check') THEN
    ALTER TABLE "PriceBookRule" ADD CONSTRAINT "PriceBookRule_basis_values_check" CHECK ("basis" IN ('REFERENCE','COST_PLUS','BULK_RATE','FIXED_CENTS','RETAIL_PRICE'));
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'PriceBookRule_basis_retail_price_buylist_only_check') THEN
    ALTER TABLE "PriceBookRule" ADD CONSTRAINT "PriceBookRule_basis_retail_price_buylist_only_check" CHECK ("basis" <> 'RETAIL_PRICE' OR "family" = 'BUYLIST');
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'PriceBookRule_basis_fixed_needs_cents_check') THEN
    ALTER TABLE "PriceBookRule" ADD CONSTRAINT "PriceBookRule_basis_fixed_needs_cents_check" CHECK ("basis" <> 'FIXED_CENTS' OR ("fixedCents" IS NOT NULL AND "fixedCents" >= 1));
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'PriceBookRule_percentBps_range_check') THEN
    ALTER TABLE "PriceBookRule" ADD CONSTRAINT "PriceBookRule_percentBps_range_check" CHECK ("percentBps" BETWEEN 0 AND 100000);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'PriceBookRule_addCents_range_check') THEN
    ALTER TABLE "PriceBookRule" ADD CONSTRAINT "PriceBookRule_addCents_range_check" CHECK ("addCents" BETWEEN -1000000 AND 1000000);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'PriceBookRule_ref_band_order_check') THEN
    ALTER TABLE "PriceBookRule" ADD CONSTRAINT "PriceBookRule_ref_band_order_check" CHECK ("refMinCents" IS NULL OR "refMaxCents" IS NULL OR "refMinCents" <= "refMaxCents");
