  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'PriceBookRule_floor_ceiling_order_check') THEN
    ALTER TABLE "PriceBookRule" ADD CONSTRAINT "PriceBookRule_floor_ceiling_order_check" CHECK ("floorCents" IS NULL OR "ceilingCents" IS NULL OR "floorCents" <= "ceilingCents");
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'PriceBookRule_priority_range_check') THEN
    ALTER TABLE "PriceBookRule" ADD CONSTRAINT "PriceBookRule_priority_range_check" CHECK ("priority" BETWEEN 1 AND 10000);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'PriceBookRule_creditBps_buylist_range_check') THEN
    ALTER TABLE "PriceBookRule" ADD CONSTRAINT "PriceBookRule_creditBps_buylist_range_check" CHECK ("creditBps" IS NULL OR ("family" = 'BUYLIST' AND "creditBps" BETWEEN 10000 AND 30000));
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'PriceBookRule_minOfferCents_buylist_check') THEN
    ALTER TABLE "PriceBookRule" ADD CONSTRAINT "PriceBookRule_minOfferCents_buylist_check" CHECK ("minOfferCents" IS NULL OR "family" = 'BUYLIST');
  END IF;
END $$;

