DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'PriceBookRunItem_state_values_check') THEN
    ALTER TABLE "PriceBookRunItem" ADD CONSTRAINT "PriceBookRunItem_state_values_check" CHECK ("state" IN ('PENDING','APPLIED','SKIPPED','CHANGED_SINCE_PREVIEW','UNDONE','UNDO_SKIPPED','FAILED'));
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'PriceBookRunItem_oldPriceCents_min_check') THEN
    ALTER TABLE "PriceBookRunItem" ADD CONSTRAINT "PriceBookRunItem_oldPriceCents_min_check" CHECK ("oldPriceCents" IS NULL OR "oldPriceCents" >= 0);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'PriceBookRunItem_newPriceCents_min_check') THEN
    ALTER TABLE "PriceBookRunItem" ADD CONSTRAINT "PriceBookRunItem_newPriceCents_min_check" CHECK ("newPriceCents" IS NULL OR "newPriceCents" >= 0);
  END IF;
END $$;
